#include <algorithm>
#include <array>
#include <cstdint>
#include <fstream>
#include <functional>
#include <iostream>
#include <sstream>
#include <unordered_map>
#include <unordered_set>
#include <vector>
using namespace std; constexpr int D=5,U=16807,N=367;
array<int,D> dec5(int v){array<int,D>a{};for(int i=0;i<D;i++){a[i]=v%7;v/=7;}return a;} int enc5(const array<int,D>&a){int v=0,m=1;for(int i=0;i<D;i++){v+=a[i]*m;m*=7;}return v;}
vector<int> parse(const string&s,const string&key){vector<int>a;auto p=s.find("\""+key+"\"");p=s.find('[',p);auto e=s.find(']',p);stringstream ss(s.substr(p+1,e-p-1));while(ss){int x;if(ss>>x)a.push_back(x);if(ss.peek()==',')ss.get();else{ss.clear();char c;ss>>c;}}return a;}
struct Key{array<uint16_t,6>a{};bool operator==(Key const&o)const{return a==o.a;}bool operator<(Key const&o)const{return a<o.a;}}; struct KH{size_t operator()(Key const&k)const noexcept{size_t h=0;for(auto x:k.a)h=h*1000003u+x;return h;}};
struct Cand{int v;Key k;int n;};
bool conf(int a,int b,const vector<array<int,D>>&dig){auto x=dig[a],y=dig[b];for(int k=0;k<D;k++){int z=(x[k]-y[k]+7)%7;if(z!=0&&z!=1&&z!=6)return false;}return true;}
bool find7(vector<int> p,const vector<array<int,D>>&dig,vector<int>&out){sort(p.begin(),p.end());p.erase(unique(p.begin(),p.end()),p.end());vector<int>ch;function<bool(int)>dfs=[&](int s){if(ch.size()==7){out=ch;return true;}if((int)ch.size()+(int)p.size()-s<7)return false;for(int i=s;i<(int)p.size();i++){bool ok=true;for(int z:ch)if(conf(z,p[i],dig)){ok=false;break;}if(!ok)continue;ch.push_back(p[i]);if(dfs(i+1))return true;ch.pop_back();}return false;};return dfs(0);}
Key subvec(const vector<uint16_t>&v,unsigned mask){Key k{};int j=0;for(unsigned i=0;i<v.size();i++)if(mask>>i&1)k.a[j++]=v[i];return k;} Key sub6(const Key&u,unsigned mask){Key k{};int j=0;for(int i=0;i<6;i++)if(mask>>i&1)k.a[j++]=u.a[i];return k;}
int ksize(const Key&k){int n=0;while(n<6&&k.a[n])n++;return n;}
int main(int argc,char**argv){if(argc!=2){cerr<<"usage: c7p5_r6_c4 I0_JSON\n";return 2;}ifstream in(argv[1]);string s((istreambuf_iterator<char>(in)),{});auto A=parse(s,"I0");vector<int>idx(U,-1);for(int i=0;i<N;i++)idx[A[i]]=i;vector<array<int,D>>dig(U);for(int v=0;v<U;v++)dig[v]=dec5(v);array<int,D>w{};vector<Cand>cs;unordered_map<Key,vector<int>,KH> groups;array<long long,12>cnt{};
for(int v=0;v<U;v++){if(idx[v]>=0)continue;vector<int>bs;auto d=dig[v];for(int m=0;m<243;m++){int z=m;for(int k=0;k<D;k++){int r=z%3-1;z/=3;w[k]=(d[k]+r+7)%7;}int q=enc5(w);if(idx[q]>=0)bs.push_back(idx[q]);}sort(bs.begin(),bs.end());bs.erase(unique(bs.begin(),bs.end()),bs.end());cnt[bs.size()]++;if(bs.empty()||bs.size()>6)continue;Cand c{};c.v=v;c.n=bs.size();for(int i=0;i<c.n;i++)c.k.a[i]=bs[i]+1;cs.push_back(c);groups[c.k].push_back(v);}cerr<<"cands="<<cs.size()<<" groups="<<groups.size()<<"\n";
unordered_map<Key,vector<uint16_t>,KH> E1; unordered_map<Key,vector<uint32_t>,KH> E2; vector<Key> anchors; unordered_set<Key,KH> seenAnchor;
for(auto const&kv:groups){auto k=kv.first;int n=ksize(k);if(n==4&&seenAnchor.insert(k).second)anchors.push_back(k);if(n<2||n>4)continue;vector<uint16_t> vals(n);for(int i=0;i<n;i++)vals[i]=k.a[i];for(int t=0;t<n;t++){vector<uint16_t> core;for(int i=0;i<n;i++)if(i!=t)core.push_back(vals[i]);if(core.empty())continue;Key ck{};for(int i=0;i<(int)core.size();i++)ck.a[i]=core[i];E1[ck].push_back(vals[t]);}if(n>=3)for(int s=0;s<n;s++)for(int t=s+1;t<n;t++){vector<uint16_t>core;for(int i=0;i<n;i++)if(i!=s&&i!=t)core.push_back(vals[i]);if(core.empty())continue;Key ck{};for(int i=0;i<(int)core.size();i++)ck.a[i]=core[i];uint16_t x=vals[s],y=vals[t];if(x>y)swap(x,y);E2[ck].push_back((uint32_t(x)<<16)|y);}}
for(auto&kv:E1){auto&v=kv.second;sort(v.begin(),v.end());v.erase(unique(v.begin(),v.end()),v.end());}for(auto&kv:E2){auto&v=kv.second;sort(v.begin(),v.end());v.erase(unique(v.begin(),v.end()),v.end());}
auto ext1=[&](vector<uint16_t>cur){vector<uint16_t>out;int m=cur.size();for(unsigned mask=1;mask<(1u<<m);mask++){int pc=__builtin_popcount(mask);if(pc>3)continue;Key ck=subvec(cur,mask);auto it=E1.find(ck);if(it==E1.end())continue;for(auto x:it->second)if(!binary_search(cur.begin(),cur.end(),x))out.push_back(x);}sort(out.begin(),out.end());out.erase(unique(out.begin(),out.end()),out.end());return out;};
auto ext2=[&](vector<uint16_t>cur){vector<uint32_t>out;int m=cur.size();for(unsigned mask=1;mask<(1u<<m);mask++){int pc=__builtin_popcount(mask);if(pc>2)continue;Key ck=subvec(cur,mask);auto it=E2.find(ck);if(it==E2.end())continue;for(auto xy:it->second){uint16_t x=xy>>16,y=xy;if(!binary_search(cur.begin(),cur.end(),x)&&!binary_search(cur.begin(),cur.end(),y))out.push_back(xy);}}sort(out.begin(),out.end());out.erase(unique(out.begin(),out.end()),out.end());return out;};
auto poolFor=[&](Key const&u){vector<int>p;for(unsigned mask=1;mask<64;mask++){auto it=groups.find(sub6(u,mask));if(it!=groups.end())p.insert(p.end(),it->second.begin(),it->second.end());}sort(p.begin(),p.end());p.erase(unique(p.begin(),p.end()),p.end());return p;};
unordered_set<Key,KH> seenU;size_t generated=0,tested=0,maxpool=0;for(auto const&A4:anchors){vector<uint16_t> av={A4.a[0],A4.a[1],A4.a[2],A4.a[3]};auto xs=ext1(av);for(auto x:xs){vector<uint16_t> b=av;b.push_back(x);sort(b.begin(),b.end());auto ys=ext1(b);for(auto y:ys){if(y==x)continue;array<uint16_t,6>z{A4.a[0],A4.a[1],A4.a[2],A4.a[3],x,y};sort(z.begin(),z.end());Key u{};u.a=z;if(!seenU.insert(u).second)continue;generated++;auto p=poolFor(u);maxpool=max(maxpool,p.size());if(p.size()<7)continue;tested++;vector<int>ch;if(find7(p,dig,ch)){cout<<"FOUND c4 remove=";for(int i=0;i<6;i++)cout<<(i?",":"")<<A[u.a[i]-1];cout<<" add=";for(int i=0;i<7;i++)cout<<(i?",":"")<<ch[i];cout<<" pool="<<p.size()<<"\n";return 0;}}}
auto ps=ext2(av);for(auto xy:ps){uint16_t x=xy>>16,y=xy;array<uint16_t,6>z{A4.a[0],A4.a[1],A4.a[2],A4.a[3],x,y};sort(z.begin(),z.end());Key u{};u.a=z;if(!seenU.insert(u).second)continue;generated++;auto p=poolFor(u);maxpool=max(maxpool,p.size());if(p.size()<7)continue;tested++;vector<int>ch;if(find7(p,dig,ch)){cout<<"FOUND c4-directpair remove=";for(int i=0;i<6;i++)cout<<(i?",":"")<<A[u.a[i]-1];cout<<" add=";for(int i=0;i<7;i++)cout<<(i?",":"")<<ch[i];cout<<" pool="<<p.size()<<"\n";return 0;}}}
cout<<"NONE c4 anchors="<<anchors.size()<<" owner6="<<generated<<" tested="<<tested<<" maxpool="<<maxpool<<"\n";}
